import{_ as o,c as a,o as t,a2 as s}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1780466351000}'),i={name:"guide/installation.md"};function n(l,e,r,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>This page explains how to install Gomoku on macOS and covers common issues you may encounter.</p><h2 id="download-options" tabindex="-1">Download Options <a class="header-anchor" href="#download-options" aria-label="Permalink to &quot;Download Options&quot;">​</a></h2><ul><li><strong>Mac App Store</strong> — If an App Store build is published, install from the App Store for automatic updates.</li><li><strong>GitHub Releases</strong> — Download the latest macOS build (.dmg or .zip) from the project&#39;s Releases page: <code>https://github.com/your-org/gomoku/releases</code>.</li></ul><p>If you don&#39;t see an App Store entry yet, use the GitHub Releases download.</p><h2 id="installing-from-a-dmg-recommended-for-most-users" tabindex="-1">Installing from a .dmg (recommended for most users) <a class="header-anchor" href="#installing-from-a-dmg-recommended-for-most-users" aria-label="Permalink to &quot;Installing from a .dmg (recommended for most users)&quot;">​</a></h2><ol><li>Download the latest <code>.dmg</code> from the Releases page.</li><li>Double-click the downloaded <code>.dmg</code> to open it.</li><li>Drag the <code>Gomoku.app</code> icon into your <code>Applications</code> folder.</li><li>Eject the mounted image and open <code>Gomoku</code> from <code>Applications</code>.</li></ol><p>If macOS prevents opening the app (Gatekeeper), open <strong>System Settings → Privacy &amp; Security</strong> and click <strong>Open Anyway</strong> for Gomoku, or right-click the app and choose <strong>Open</strong>.</p><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><p>On first run Gomoku may request the following permissions:</p><ul><li><strong>Local Network</strong> — required for LAN (局域网) play so other devices on your Wi‑Fi can discover and join games.</li><li><strong>Files and Folders</strong> — to save and open game records (SGF) and settings.</li><li><strong>Accessibility / Screen Recording</strong> — optional; only needed if you enable auxiliary features that capture the screen or use overlay helpers.</li></ul><p>Grant permissions when prompted; you can change them later in <strong>System Settings → Privacy &amp; Security</strong>.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><ul><li>If you installed from the <strong>Mac App Store</strong>, updates are handled automatically.</li><li>If you use the <strong>GitHub Releases</strong> build, download the newer release and replace the app in <code>Applications</code>.</li></ul><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>To uninstall Gomoku:</p><ol><li>Quit Gomoku</li><li>Drag <code>Gomoku.app</code> from <code>Applications</code> to the Trash</li><li>(Optional) Remove app data and logs:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.gomoku</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/gomoku</span></span></code></pre></div><p>See <code>docs/macos-sandbox-paths.md</code> in the source project for details about sandboxed paths.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>macOS</strong>: Monterey (12) or later recommended</li><li><strong>CPU</strong>: Apple Silicon (M-series) or Intel (64-bit)</li><li><strong>Memory</strong>: 4GB minimum, 8GB recommended</li><li><strong>Storage</strong>: ~200 MB (varies by build)</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>If macOS blocks the app at launch, open <strong>System Settings → Privacy &amp; Security</strong> and allow Gomoku to open.</li><li>For LAN issues, ensure all devices are on the same Wi‑Fi network and that <strong>Local Network</strong> permission was granted.</li><li>If you see a notarization warning, download a signed/notarized build from Releases or the App Store.</li></ul><p>If you need more help, see the Troubleshooting guide or open an issue on the project repository.</p>`,24)])])}const m=o(i,[["render",n]]);export{h as __pageData,m as default};
